import { decodeSignalPreKeyRow } from 'zapo-js/signal';
import { asNumber, resolvePositive, toBoolOrUndef } from 'zapo-js/util';
import { BaseSqliteStore } from './BaseSqliteStore.js';
import { repeatSqlToken } from './sql-utils.js';
const DEFAULTS = Object.freeze({
    preKeyBatchSize: 500
});
export class WaPreKeySqliteStore extends BaseSqliteStore {
    constructor(options, storeOptions = {}) {
        super(options, ['signal']);
        this.preKeyBatchSize = resolvePositive(storeOptions.preKeyBatchSize, DEFAULTS.preKeyBatchSize, 'signal.sqlite.preKeyBatchSize');
    }
    async putPreKey(record) {
        const db = await this.getConnection();
        this.ensureMetaRow(db);
        this.upsertPreKey(db, record);
        db.run(`UPDATE signal_meta
             SET next_prekey_id = MAX(next_prekey_id, ?)
             WHERE session_id = ?`, [record.keyId + 1, this.options.sessionId]);
    }
    async getOrGenPreKeys(count, generator) {
        if (!Number.isSafeInteger(count) || count <= 0) {
            throw new Error(`invalid prekey count: ${count}`);
        }
        while (true) {
            const reservation = await this.withTransaction((db) => {
                this.ensureMetaRow(db);
                const available = this.selectAvailablePreKeys(db, count);
                const missing = count - available.length;
                if (missing <= 0) {
                    return {
                        available,
                        reservedKeyIds: []
                    };
                }
                const nextPreKeyId = this.getMeta(db).nextPreKeyId;
                const reservedKeyIds = new Array(missing);
                for (let index = 0; index < missing; index += 1) {
                    reservedKeyIds[index] = nextPreKeyId + index;
                }
                db.run(`UPDATE signal_meta
                     SET next_prekey_id = MAX(next_prekey_id, ?)
                     WHERE session_id = ?`, [nextPreKeyId + missing, this.options.sessionId]);
                return {
                    available,
                    reservedKeyIds
                };
            });
            if (reservation.reservedKeyIds.length === 0) {
                return reservation.available;
            }
            const generated = new Array(reservation.reservedKeyIds.length);
            let maxGeneratedKeyId = reservation.reservedKeyIds[reservation.reservedKeyIds.length - 1];
            for (let index = 0; index < reservation.reservedKeyIds.length; index += 1) {
                const requestedKeyId = reservation.reservedKeyIds[index];
                const generatedRecord = await generator(requestedKeyId);
                generated[index] = generatedRecord;
                if (generatedRecord.keyId > maxGeneratedKeyId) {
                    maxGeneratedKeyId = generatedRecord.keyId;
                }
            }
            const insertedCount = await this.withTransaction((db) => {
                this.ensureMetaRow(db);
                const before = this.countPreKeys(db);
                for (const record of generated) {
                    this.insertPreKeyIfMissing(db, record);
                }
                db.run(`UPDATE signal_meta
                     SET next_prekey_id = MAX(next_prekey_id, ?)
                     WHERE session_id = ?`, [maxGeneratedKeyId + 1, this.options.sessionId]);
                return this.countPreKeys(db) - before;
            });
            // No new rows: the generator returned already-stored key ids (insert
            // no-op). Bail instead of looping; robust to a concurrent consume.
            if (insertedCount === 0) {
                throw new Error('getOrGenPreKeys made no progress; the generator returned key ids ' +
                    'that collide with stored prekeys');
            }
            const available = await this.withTransaction((db) => this.selectAvailablePreKeys(db, count));
            if (available.length >= count) {
                return available;
            }
        }
    }
    async getPreKeyById(keyId) {
        const db = await this.getConnection();
        const row = db.get(`SELECT key_id, pub_key, priv_key, uploaded
             FROM signal_prekey
             WHERE session_id = ? AND key_id = ?`, [this.options.sessionId, keyId]);
        return row ? decodeSignalPreKeyRow(row) : null;
    }
    async getPreKeysById(keyIds) {
        if (keyIds.length === 0) {
            return [];
        }
        const db = await this.getConnection();
        const uniqueKeyIds = [...new Set(keyIds)];
        const byId = new Map();
        for (let start = 0; start < uniqueKeyIds.length; start += this.preKeyBatchSize) {
            const end = Math.min(start + this.preKeyBatchSize, uniqueKeyIds.length);
            const batchLength = end - start;
            const placeholders = repeatSqlToken('?', batchLength, ', ');
            const params = [this.options.sessionId];
            for (let index = start; index < end; index += 1) {
                params.push(uniqueKeyIds[index]);
            }
            const rows = db.all(`SELECT key_id, pub_key, priv_key, uploaded
                 FROM signal_prekey
                 WHERE session_id = ? AND key_id IN (${placeholders})`, params);
            for (const row of rows) {
                const record = decodeSignalPreKeyRow(row);
                byId.set(record.keyId, record);
            }
        }
        const records = new Array(keyIds.length);
        for (let index = 0; index < keyIds.length; index += 1) {
            records[index] = byId.get(keyIds[index]) ?? null;
        }
        return records;
    }
    async consumePreKeyById(keyId) {
        return this.withTransaction((db) => {
            const row = db.get(`SELECT key_id, pub_key, priv_key, uploaded
                 FROM signal_prekey
                 WHERE session_id = ? AND key_id = ?`, [this.options.sessionId, keyId]);
            if (!row) {
                return null;
            }
            db.run(`DELETE FROM signal_prekey
                 WHERE session_id = ? AND key_id = ?`, [this.options.sessionId, keyId]);
            return decodeSignalPreKeyRow(row);
        });
    }
    async getOrGenSinglePreKey(generator) {
        const records = await this.getOrGenPreKeys(1, generator);
        return records[0];
    }
    async markKeyAsUploaded(keyId) {
        const db = await this.getConnection();
        const meta = this.getMeta(db);
        if (keyId < 0 || keyId >= meta.nextPreKeyId) {
            throw new Error(`prekey ${keyId} is out of boundary`);
        }
        db.run(`UPDATE signal_prekey
             SET uploaded = 1
             WHERE session_id = ? AND key_id <= ?`, [this.options.sessionId, keyId]);
    }
    async setServerHasPreKeys(value) {
        const db = await this.getConnection();
        this.ensureMetaRow(db);
        db.run(`UPDATE signal_meta
             SET server_has_prekeys = ?
             WHERE session_id = ?`, [value ? 1 : 0, this.options.sessionId]);
    }
    async getServerHasPreKeys() {
        const db = await this.getConnection();
        const meta = this.getMeta(db);
        return meta.serverHasPreKeys;
    }
    async clear() {
        await this.withTransaction((db) => {
            db.run('DELETE FROM signal_prekey WHERE session_id = ?', [this.options.sessionId]);
            db.run(`UPDATE signal_meta
                 SET server_has_prekeys = 0, next_prekey_id = 1
                 WHERE session_id = ?`, [this.options.sessionId]);
        });
    }
    selectAvailablePreKeys(db, limit) {
        const rows = db.all(`SELECT key_id, pub_key, priv_key, uploaded
             FROM signal_prekey
             WHERE session_id = ? AND uploaded = 0
             ORDER BY key_id ASC
             LIMIT ?`, [this.options.sessionId, limit]);
        const records = new Array(rows.length);
        for (let index = 0; index < rows.length; index += 1) {
            records[index] = decodeSignalPreKeyRow(rows[index]);
        }
        return records;
    }
    countPreKeys(db) {
        const row = db.get(`SELECT COUNT(*) AS count FROM signal_prekey WHERE session_id = ?`, [this.options.sessionId]);
        return row?.count ?? 0;
    }
    upsertPreKey(db, record) {
        db.run(`INSERT INTO signal_prekey (
                session_id,
                key_id,
                pub_key,
                priv_key,
                uploaded
            ) VALUES (?, ?, ?, ?, ?)
            ON CONFLICT(session_id, key_id) DO UPDATE SET
                pub_key=excluded.pub_key,
                priv_key=excluded.priv_key,
                uploaded=excluded.uploaded`, [
            this.options.sessionId,
            record.keyId,
            record.keyPair.pubKey,
            record.keyPair.privKey,
            record.uploaded === true ? 1 : 0
        ]);
    }
    insertPreKeyIfMissing(db, record) {
        db.run(`INSERT INTO signal_prekey (
                session_id,
                key_id,
                pub_key,
                priv_key,
                uploaded
            ) VALUES (?, ?, ?, ?, ?)
            ON CONFLICT(session_id, key_id) DO NOTHING`, [
            this.options.sessionId,
            record.keyId,
            record.keyPair.pubKey,
            record.keyPair.privKey,
            record.uploaded === true ? 1 : 0
        ]);
    }
    ensureMetaRow(db) {
        db.run(`INSERT INTO signal_meta (
                session_id,
                server_has_prekeys,
                next_prekey_id
            ) VALUES (?, 0, 1)
            ON CONFLICT(session_id) DO NOTHING`, [this.options.sessionId]);
    }
    getMeta(db) {
        this.ensureMetaRow(db);
        const row = db.get(`SELECT server_has_prekeys, next_prekey_id
             FROM signal_meta
             WHERE session_id = ?`, [this.options.sessionId]);
        return {
            serverHasPreKeys: toBoolOrUndef(row.server_has_prekeys) === true,
            nextPreKeyId: asNumber(row.next_prekey_id, 'signal_meta.next_prekey_id')
        };
    }
}
